UPDATE export_job
SET status       = 'done',
    completed_at = now()
WHERE corporate_number = #{corporateNumber}
  AND checkpoint_date = #{checkpointDate}
  AND claimed_by = #{instanceId}

UPDATE export_job
SET status = 'failed'
WHERE corporate_number = #{corporateNumber}
  AND checkpoint_date = #{checkpointDate}
  AND claimed_by = #{instanceId}
